// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address nonOwner, uint256 seedAmount, uint256 withdrawAmount) public {
        vm.assume(nonOwner != address(0) && nonOwner != address(this) && nonOwner != address(c));
        vm.assume(seedAmount > 0 && withdrawAmount <= seedAmount);
        vm.assume(nonOwner != c.owner());

        vm.deal(address(c), seedAmount);
        uint256 balanceBefore = address(c).balance;

        vm.prank(nonOwner);
        try c.withdrawAll() {} catch {}

        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter == balanceBefore);
    }
}
